(function(){
const general='Original teaching example; standard Japanese';
const sources={tokyo:'https://www.gotokyo.org/book/wp-content/uploads/2025/09/2509_HowtoEnjoyTokyo_EN_low.pdf',shopping:'https://faq.japan-travel.jnto.go.jp/en/guide/shopping-q-and-a/',money:'https://www.mof.go.jp/english/policy/currency/coin/circulating_coins/list.htm',cashless:'https://www.japan.travel/en/plan/cashless-payments-in-japan/',bags:'https://www.japan.travel/en/responsible-travel-guide/japanese-customs-and-etiquette/'};
const p=([ja,kana,romaji,meaning])=>({ja,kana,romaji,meaning});
const d=(speaker,a)=>({speaker,...p(a)});
const w=(a,distractors,say)=>({kind:'word',...p(a),distractors,say,src:general,status:'general'});
const s=(a,tiles,distractors,say)=>({kind:'sentence',...p(a),tiles:tiles.map(([ja,romaji])=>({ja,romaji})),distractors:distractors.map(([ja,romaji])=>({ja,romaji})),transfer:false,say,src:general,status:'general'});
const g=(title,explanation,examples,q,options,answer,why)=>({kind:'grammar',title,explanation,examples:examples.map(p),quiz:{q,options,answer,why},say:explanation,src:general,status:'general'});
const c=(title,place,body,src,q,options,answer,why)=>({kind:'culture',title,place,body,src,quiz:{q,options,answer,why},say:body,status:'sourced'});
const q=(title,scene,prompt,options,answer)=>({kind:'scenario',title,scene,q:prompt,options:options.map(([text,why])=>({text,why})),answer,transfer:true,say:'Use the situation and relationship to choose a useful response.',src:general,status:'general'});
const lesson=(n,title,scene,mission,dialogue,items)=>({id:`u4l${n}`,title,scene,mission,dialogue,items:items.map((item,i)=>({id:`u4-${n}-${i+1}`,...item}))});
const unit={id:'u4',title:'Everyday shopping',blurb:'Choose a favorite, check the fit, and handle the checkout with confidence.',place:'A stationery shop and a clothing store',focus:'This and that · prices · sizes · payment',lessons:[
lesson(1,'This one, that one','At a stationery shop, you compare notebooks. One is in your hand, another is beside the clerk, and a third is on a distant shelf.','Point out the notebook near you with kore. Then refer to the one near the clerk with sore.',[
d('You',['これはいくらですか？','これはいくらですか？','Kore wa ikura desu ka?','How much is this?']),
d('Clerk',['それは三百円です。','それはさんびゃくえんです。','Sore wa sanbyaku-en desu.','That is three hundred yen.']),
d('You',['このノートをください。','このノートをください。','Kono nōto o kudasai.','This notebook, please.'])],[
w(['これ','これ','kore','This one (near the speaker)'],['That one near you','That one over there','Which one?'],'Kore stands on its own as a noun: this thing near me.'),
w(['それ','それ','sore','That one (near the listener, in this scene)'],['This one near me','That one far from both of us','Who?'],'In a visible shopping scene, sore often points to something near the person you are speaking to.'),
w(['あれ','あれ','are','That one over there (away from both people)'],['This one in my hand','This price','Where?'],'Are points farther away from both speaker and listener in this scene.'),
w(['この','この','kono','This … (before a noun)'],['Where','How many','That one over there'],'Kono needs a noun after it: kono nōto means this notebook.'),
s(['このノートをください。','このノートをください。','Kono nōto o kudasai.','This notebook, please.'],[['この','kono'],['ノート','nōto'],['を','o'],['ください','kudasai']],[['これ','kore']],'Use kono before a noun. Kore already means “this one” and does not directly modify nōto.'),
g('Kore stands alone; kono takes a noun','Kore means “this one.” Kono means “this” before a noun. The pairs sore/sono and are/ano work in the same way. Which one you choose depends on the speaker’s viewpoint.',[['これをください。','これをください。','Kore o kudasai.','This one, please.'],['このノートをください。','このノートをください。','Kono nōto o kudasai.','This notebook, please.']],'Which phrase correctly means “this notebook”?',['これノート (kore nōto)','このノート (kono nōto)','ここノート (koko nōto)'],'このノート (kono nōto)','Kono modifies the noun nōto. Kore is already a standalone “this one.”'),
c('Ask before opening','A stationery shop','If you want to inspect the contents of a sealed product, ask an employee before opening it. Return an item to its original place if you decide against it. A sample may be available.',sources.tokyo,'You want to see inside a sealed notebook package. What should you do first?',['Open the package and replace it later','Ask the staff whether you can see a sample','Assume every packaged item is a display sample'],'Ask the staff whether you can see a sample','An employee can explain how this shop lets you inspect the product.'),
q('Near the clerk','A notebook is beside the clerk, away from you. You point to it and want to say “that one.”','Which word fits the visible positions?',[
['それ (sore)','Sore points to the item near the listener in this scene.'],['これ (kore)','Kore would point to an item near you.'],['あれ (are)','Are would fit an item away from both of you.']],0)
]),
lesson(2,'Hear the price','You are comparing small notebooks and pens. All prices in this practice scene are invented examples, not current shop prices.','Read 100, 300, 600, and 800 yen aloud. Ask for repetition if you cannot distinguish the amount.',[
d('You',['このペンはいくらですか？','このペンはいくらですか？','Kono pen wa ikura desu ka?','How much is this pen?']),
d('Clerk',['六百円です。','ろっぴゃくえんです。','Roppyaku-en desu.','It is six hundred yen.']),
d('You',['六百円ですね。','ろっぴゃくえんですね。','Roppyaku-en desu ne.','Six hundred yen, correct?']),
d('Clerk',['はい。','はい。','Hai.','Yes.'])],[
w(['百円','ひゃくえん','hyaku-en','100 yen'],['10 yen','1,000 yen','500 yen'],'Hyaku is one hundred; en is the Japanese pronunciation of yen.'),
w(['三百円','さんびゃくえん','sanbyaku-en','300 yen'],['30 yen','600 yen','3,000 yen'],'The hundred part changes to byaku after san. Learn sanbyaku as a whole.'),
w(['六百円','ろっぴゃくえん','roppyaku-en','600 yen'],['60 yen','300 yen','6,000 yen'],'Roku + hyaku becomes roppyaku. Hold the p made by the small っ.'),
w(['八百円','はっぴゃくえん','happyaku-en','800 yen'],['80 yen','500 yen','8,000 yen'],'Hachi + hyaku becomes happyaku, with a held p.'),
s(['これは六百円です。','これはろっぴゃくえんです。','Kore wa roppyaku-en desu.','This is six hundred yen.'],[['これは','kore wa'],['六百円','roppyaku-en'],['です','desu']],[['八百円','happyaku-en']],'Set the item as the topic, give the amount in yen, and finish with desu.'),
g('Hundreds have sound changes','Hyaku is 100. The forms sanbyaku (300), roppyaku (600), and happyaku (800) change sound; do not mechanically join san, roku, or hachi to hyaku. Price practice is also pronunciation practice.',[['三百円です。','さんびゃくえんです。','Sanbyaku-en desu.','It is three hundred yen.'],['八百円です。','はっぴゃくえんです。','Happyaku-en desu.','It is eight hundred yen.']],'Which reading matches 六百円?',['Rokuhyaku-en','Roppyaku-en','Happyaku-en'],'Roppyaku-en','The standard form for six hundred is roppyaku, with the held p.'),
c('Learn the coins as well as the words','A checkout counter','Japan’s circulating coin denominations include 1, 5, 10, 50, 100, and 500 yen. Recognizing the value helps you connect spoken amounts with the coins in your hand.',sources.money,'You need 600 yen and choose one 500-yen coin. Which coin completes the amount?',['A 100-yen coin','A 10-yen coin','A 50-yen coin'],'A 100-yen coin','Five hundred plus one hundred is six hundred yen.'),
q('A price you almost caught','The clerk says “八百円です” (Happyaku-en desu). You want to confirm the number rather than guess.','Which response checks the same amount?',[
['三百円ですね (sanbyaku-en desu ne) — Three hundred yen, correct?','That changes the amount to 300.'],['六百円ですね (roppyaku-en desu ne) — Six hundred yen, correct?','That changes the amount to 600.'],['八百円ですね (happyaku-en desu ne) — Eight hundred yen, correct?','This repeats the stated amount for confirmation.']],2)
]),
lesson(3,'Find a comfortable fit','A shirt you like is too small. You ask about a larger size and ask before trying it on.','Tell the clerk that this size is small. Ask for a larger size, then ask permission to try it on.',[
d('You',['これは少し小さいです。','これはすこしちいさいです。','Kore wa sukoshi chiisai desu.','This is a little small.']),
d('You',['大きいサイズはありますか？','おおきいサイズはありますか？','Ōkii saizu wa arimasu ka?','Do you have a large size?']),
d('Clerk',['はい、あります。','はい、あります。','Hai, arimasu.','Yes, we do.']),
d('You',['試着してもいいですか？','しちゃくしてもいいですか？','Shichaku shite mo ii desu ka?','May I try it on?'])],[
w(['大きい','おおきい','ōkii','Large / big'],['Small','Expensive','New'],'Keep the long ō and ii. This adjective can go directly before a noun.'),
w(['小さい','ちいさい','chiisai','Small'],['Large','Cheap','Old'],'Chiisai has a long ii sound. Here it describes the fit.'),
w(['サイズ','サイズ','saizu','Size'],['Color','Price','Fabric'],'A useful katakana word when asking about clothing.'),
w(['試着してもいいですか','しちゃくしてもいいですか','shichaku shite mo ii desu ka','May I try it on?'],['May I pay now?','Where is the exit?','Do you have a receipt?'],'Learn this permission request as a whole phrase before building other requests later.'),
s(['大きいサイズはありますか？','おおきいサイズはありますか？','Ōkii saizu wa arimasu ka?','Do you have a large size?'],[['大きい','ōkii'],['サイズ','saizu'],['は','wa'],['ありますか','arimasu ka']],[['小さい','chiisai']],'The adjective ōkii comes before saizu; use the availability question you already know.'),
g('An i-adjective before a noun','Ōkii and chiisai can directly modify a noun: ōkii saizu, “a large size.” When making a polite statement, add desu after the adjective: chiisai desu, “it is small.”', [['大きいサイズ','おおきいサイズ','ōkii saizu','A large size'],['小さいです。','ちいさいです。','Chiisai desu.','It is small.']],'Which phrase means “a small size”?',['小さいサイズ (chiisai saizu)','小さいですサイズ (chiisai desu saizu)','サイズ小さいを (saizu chiisai o)'],'小さいサイズ (chiisai saizu)','The adjective directly precedes the noun; desu does not go between them.'),
c('Let the fitting room guide you','A clothing shop','Ask staff before trying on clothes. They can show you the fitting room and explain local instructions, which may include removing shoes or using a face cover. Follow the directions at that store.',sources.shopping,'The clerk asks you to remove your shoes before using this fitting room. What fits?',['Follow the instruction or explain if you need assistance','Assume the rule from your previous shop applies instead','Enter immediately because fitting rooms never have instructions'],'Follow the instruction or explain if you need assistance','The clerk is giving the instructions for this particular fitting room.'),
q('The shirt is too small','You have tried a shirt with permission. It is too small, and you want to ask about a larger size.','Which question matches your need?',[
['小さいサイズはありますか (chiisai saizu wa arimasu ka) — Do you have a small size?','That asks for a small size when you need a larger one.'],['大きいサイズはありますか (ōkii saizu wa arimasu ka) — Do you have a large size?','This asks about the size direction you need.'],['これはいくらですか (kore wa ikura desu ka) — How much is this?','The price does not resolve the fit.']],1)
]),
lesson(4,'Choose how to pay','At checkout, you want to use a card. You check first because shops accept different payment methods.','Ask if you can use a card. If the clerk says no, say you will pay in cash.',[
d('You',['カードは使えますか？','カードはつかえますか？','Kādo wa tsukaemasu ka?','Can I use a card?']),
d('Clerk',['すみません。現金だけです。','すみません。げんきんだけです。','Sumimasen. Genkin dake desu.','Sorry. Cash only.']),
d('You',['では、現金でお願いします。','では、げんきんでおねがいします。','Dewa, genkin de onegaishimasu.','Then I will pay in cash, please.']),
d('Clerk',['レシートです。','レシートです。','Reshīto desu.','Here is your receipt.'])],[
w(['現金','げんきん','genkin','Cash'],['A card','A receipt','A discount'],'Genkin means physical money, as opposed to paying by card or another method.'),
w(['カード','カード','kādo','Card (payment card here)'],['Cash','A price tag','A shopping bag'],'The long ā matters. Check which cards the shop accepts.'),
w(['使えますか','つかえますか','tsukaemasu ka','Can I use it? / Is it usable?'],['Have you eaten?','Is it large?','Where are you going?'],'This asks about ability or availability of use. For payment, name the method first.'),
w(['レシート','レシート','reshīto','Receipt'],['Train ticket','Menu','Banknote'],'A katakana loanword with a long ī sound. A receipt records a purchase.'),
s(['カードは使えますか？','カードはつかえますか？','Kādo wa tsukaemasu ka?','Can I use a card?'],[['カード','kādo'],['は','wa'],['使えます','tsukaemasu'],['か','ka']],[['好きです','suki desu']],'Make the card the topic and ask whether it can be used.'),
g('De can mark the means','In genkin de, de means “with / by means of cash,” rather than a location. Context tells you its role. Genkin dake means “cash only”; dake limits the available options.',[['現金でお願いします。','げんきんでおねがいします。','Genkin de onegaishimasu.','I will pay in cash, please.'],['現金だけです。','げんきんだけです。','Genkin dake desu.','Cash only.']],'What does genkin dake desu tell you at checkout?',['Cash is one of several confirmed choices','Only cash is accepted here','All cards are accepted'],'Only cash is accepted here','Dake means “only.” This statement limits payment to cash.'),
c('Check the logo, then ask','A checkout counter','Cashless payment is common in many places, but accepted methods differ. Look for payment logos and ask about your card before relying on it. A method that worked elsewhere may not work in this shop.',sources.cashless,'Your card worked at a large store yesterday. What should you assume about today’s small shop?',['The same card must work everywhere','Its accepted methods still need checking','Every small shop takes only cash'],'Its accepted methods still need checking','Neither “cards everywhere” nor “cash only everywhere” is a reliable rule.'),
q('Cash only today','You ask about card payment. The clerk says “現金だけです” (Genkin dake desu — Cash only). You have enough cash.','Which response moves the purchase forward?',[
['現金でお願いします (genkin de onegaishimasu) — I will pay in cash, please','This matches the available payment method.'],['カードでお願いします (kādo de onegaishimasu) — By card, please','The clerk has just explained that cards are not accepted.'],['往復を一枚お願いします (ōfuku o ichimai onegaishimasu) — One round-trip ticket, please','That is a ticket request, not a payment choice for this shop.']],0)
]),
lesson(5,'A choice without pressure','You have chosen a notebook and brought your own bag. At checkout, the clerk offers a shopping bag.','Say you will take this notebook and that you do not need a bag. Then practice a polite “just looking” for another visit.',[
d('You',['これにします。','これにします。','Kore ni shimasu.','I will take this one.']),
d('Clerk',['袋は必要ですか？','ふくろはひつようですか？','Fukuro wa hitsuyō desu ka?','Do you need a bag?']),
d('You',['袋はいりません。ありがとうございます。','ふくろはいりません。ありがとうございます。','Fukuro wa irimasen. Arigatō gozaimasu.','I do not need a bag. Thank you.'])],[
w(['袋','ふくろ','fukuro','Bag'],['Receipt','Wallet','Notebook'],'At checkout, fukuro often refers to a shopping bag.'),
w(['いりません','いりません','irimasen','I do not need it'],['I do not understand','I will go','I have one hundred yen'],'Irimasen is useful for clearly declining an unneeded item. It is different from arimasen, “there is not.”'),
w(['これにします','これにします','kore ni shimasu','I will choose / take this one'],['Where is this?','How much is this?','I do not want this'],'This communicates a decision after comparing options.'),
w(['見ているだけです','みているだけです','mite iru dake desu','I am just looking'],['I will take everything','I need a bag','I want a refund'],'A polite way to explain that you are browsing, with no purchase chosen yet.'),
s(['袋はいりません。','ふくろはいりません。','Fukuro wa irimasen.','I do not need a bag.'],[['袋','fukuro'],['は','wa'],['いりません','irimasen']],[['あります','arimasu']],'Name the thing you do not need, then use wa irimasen. This is clearer than an ambiguous yes/no to an offer.'),
g('Choose with ni shimasu','Noun + ni shimasu means you decide on that option: kore ni shimasu, “I will take this.” It announces your choice; it is not a question about availability or price.',[['これにします。','これにします。','Kore ni shimasu.','I will take this one.'],['このノートにします。','このノートにします。','Kono nōto ni shimasu.','I will choose this notebook.']],'What does kore ni shimasu communicate?',['A decision to take this option','A question about where it is','A statement that it is sold out'],'A decision to take this option','Ni shimasu marks the selected option in this shopping context.'),
c('Your own bag is useful','A shop checkout','Shopping bags often carry a charge. Bringing a reusable bag lets you decline one when you do not need it. Listen to the offer and answer clearly; packaging choices can differ by shop and item.',sources.bags,'You have your own bag and do not need another. What is a clear response?',['袋はいりません (fukuro wa irimasen — I do not need a bag)','はい (hai — yes), without clarifying what you mean','Say nothing and hope the clerk guesses'],'袋はいりません (fukuro wa irimasen — I do not need a bag)','Naming the bag and saying you do not need it makes the choice clear.'),
q('Browsing before deciding','A clerk offers help while you are looking at notebooks. You have not decided to buy anything yet.','Which phrase explains your current intention?',[
['これにします (kore ni shimasu) — I will take this one','That announces a choice you have not made.'],['袋はいりません (fukuro wa irimasen) — I do not need a bag','That answers a later packaging question, not whether you are browsing.'],['見ているだけです (mite iru dake desu) — I am just looking','This tells the clerk your current intention without making a purchase commitment.']],2)
])],assessment:[
{id:'u4-check-1',...q('A scarf beside the clerk','A scarf is beside the clerk, not near you. You want its price before deciding. The clerk says it is 800 yen.','Which pair correctly asks and confirms?',[
['これにします (kore ni shimasu — I will take this), then 三百円ですね (sanbyaku-en desu ne — 300 yen, correct?)','That commits before asking and repeats the wrong amount.'],['それはいくらですか (sore wa ikura desu ka — How much is that?), then 八百円ですね (happyaku-en desu ne — 800 yen, correct?)','Sore matches the position, and happyaku-en repeats the stated price.'],['入口はどこですか (iriguchi wa doko desu ka — Where is the entrance?), then 二人です (futari desu — Two people).','These phrases ask about a place and count people rather than price the scarf.']],1)},
{id:'u4-check-2',...q('A shirt, a card, and your own tote','A shirt fits. You decide to buy it. Staff says cards are accepted and asks whether you need a bag; you already have one.','Which response communicates your decisions?',[
['これにします。カードでお願いします。袋はいりません。 (Kore ni shimasu. Kādo de onegaishimasu. Fukuro wa irimasen.) — I will take this; by card, please; no bag needed.','Each phrase matches a choice described in the scene.'],['見ているだけです (mite iru dake desu — I am just looking).','You have decided to buy, so this no longer matches.'],['現金だけです (genkin dake desu — Cash only).','That states a shop restriction rather than your chosen available method.']],0)}]};
if(typeof KOMOREBI_UNITS!=='undefined')KOMOREBI_UNITS.push(unit);if(typeof module!=='undefined')module.exports=unit;
})();
